  9→using MonoDreams.Message;
 10→using MonoDreams.State;
 11→
 12→namespace MonoDreams.System.Collision;
 13→
 14→/// <summary>
 15→/// Collision detection system supporting both BoxCollider (swept AABB) and ConvexCollider (SAT).
 16→/// Uses ColliderTag marker component to query entities with either collider type.
 17→/// Runs single-threaded because instance-level polygon buffers (_boxPolyBufA/_boxPolyBufB)
 18→/// are not thread-safe.
 19→/// </summary>
 20→public class TransformCollisionDetectionSystem<TCollisionMessage> : ISystem<GameState>
 21→    where TCollisionMessage : ICollisionMessage
 22→{
 23→    private readonly World _world;
 24→    private readonly EntitySet _activeSet;
 25→    private readonly IEnumerable<Entity> _targets;
 26→    private readonly CreateCollisionMessageDelegate<TCollisionMessage> _createCollisionMessage;
 27→
 28→    public bool IsEnabled { get; set; } = true;
 29→
 30→    public TransformCollisionDetectionSystem(
 31→        World world,
 32→        CreateCollisionMessageDelegate<TCollisionMessage> createCollisionMessage)
 33→    {
 34→        _world = world;
 35→        _createCollisionMessage = createCollisionMessage;
 36→
 37→        // Auto-tag entities when they get a collider component
 38→        world.SubscribeEntityComponentAdded<BoxCollider>(OnBoxColliderAdded);
 39→        world.SubscribeEntityComponentAdded<ConvexCollider>(OnConvexColliderAdded);
 40→
 41→        // ColliderTag unifies BoxCollider and ConvexCollider into a single query, but each
 42→        // type has its own passive/enabled semantics — those are checked at runtime in the
 43→        // collision loop via GetCollider() rather than at query level.
 44→        _activeSet = world.GetEntities()
 45→            .With<ColliderTag>()
 46→            .With<Transform>()
 47→            .AsSet();
 48→
 49→        // All enabled collider entities are potential targets
 50→        _targets = world.GetEntities()
 51→            .With<ColliderTag>()
 52→            .With<Transform>()
 53→            .AsEnumerable();
 54→    }
 55→
 56→    private static void OnBoxColliderAdded(in Entity entity, in BoxCollider _)
 57→    {
 58→        if (!entity.Has<ColliderTag>()) entity.Set<ColliderTag>();
 59→    }
 60→
 61→    private static void OnConvexColliderAdded(in Entity entity, in ConvexCollider _)
 62→    {
 63→        if (!entity.Has<ColliderTag>()) entity.Set<ColliderTag>();
 64→    }
