 66→    public void Update(GameState state)
 67→    {
 68→        // Update world vertices for all ConvexCollider entities (_targets is the superset of _activeSet)
 69→        foreach (var target in _targets)
 70→        {
 71→            if (target.Has<ConvexCollider>())
 72→            {
 73→                ref var convex = ref target.Get<ConvexCollider>();
 74→                convex.UpdateWorldVertices(target.Get<Transform>());
 75→            }
 76→        }
 77→
 78→        // Test collisions
 79→        foreach (var entity in _activeSet.GetEntities())
 80→        {
 81→            var colliderA = GetCollider(entity);
 82→            if (colliderA == null || colliderA.Passive || !colliderA.Enabled) continue;
 83→
 84→            foreach (var target in _targets)
 85→            {
 86→                if (target == entity) continue;
 87→
 88→                var colliderB = GetCollider(target);
 89→                if (colliderB == null || !colliderB.Enabled) continue;
 90→                if (!colliderB.SharesLayerWith(colliderA)) continue;
 91→
 92→                var hasBoxA = entity.Has<BoxCollider>();
 93→                var hasBoxB = target.Has<BoxCollider>();
 94→
 95→                if (hasBoxA && hasBoxB)
 96→                {
 97→                    // Box-vs-Box: existing swept AABB path (unchanged)
 98→                    TestBoxVsBox(entity, target, colliderA, colliderB);
 99→                }
100→                else
101→                {
102→                    // Any polygon pair: SAT
103→                    TestSAT(entity, target, colliderA, colliderB, hasBoxA, hasBoxB);
104→                }
105→            }
106→        }
107→    }
108→
109→    private void TestBoxVsBox(Entity entity, Entity target, ICollider colliderA, ICollider colliderB)
110→    {
111→        var boxA = entity.Get<BoxCollider>();
112→        var transformA = entity.Get<Transform>();
113→        var dynamicRect = CollisionRect.FromBounds(boxA.Bounds, transformA.Position);
114→        var displacement = transformA.Delta;
115→
116→        var boxB = target.Get<BoxCollider>();
117→        var transformB = target.Get<Transform>();
118→        var targetRect = CollisionRect.FromBounds(boxB.Bounds, transformB.Position);
119→
120→        var collides = DynamicRectVsRect(
121→            dynamicRect, displacement, targetRect,
122→            out var contactPoint, out var contactNormal, out var contactTime);
123→
124→        if (!collides || contactNormal == Vector2.Zero) return;
125→
126→        foreach (var layer in colliderB.SharedLayers(colliderA))
127→        {
128→            _world.Publish(_createCollisionMessage(entity, target, contactPoint, contactNormal, contactTime, 0f, layer));
129→        }
130→    }
131→
132→    // Reusable buffers for box-to-polygon conversion (avoids stackalloc scope issues)
133→    private readonly Vector2[] _boxPolyBufA = new Vector2[4];
134→    private readonly Vector2[] _boxPolyBufB = new Vector2[4];
135→
136→    private void TestSAT(Entity entity, Entity target, ICollider colliderA, ICollider colliderB, bool hasBoxA, bool hasBoxB)
137→    {
138→        // Broad-phase AABB rejection first (cheap)
139→        var aabbA = hasBoxA
140→            ? CollisionRect.FromBounds(entity.Get<BoxCollider>().Bounds, entity.Get<Transform>().Position)
141→            : entity.Get<ConvexCollider>().BroadPhaseAABB;
142→        var aabbB = hasBoxB
143→            ? CollisionRect.FromBounds(target.Get<BoxCollider>().Bounds, target.Get<Transform>().Position)
144→            : target.Get<ConvexCollider>().BroadPhaseAABB;
145→
146→        if (!aabbA.Intersects(aabbB)) return;
147→
148→        // Get world-space polygons for both entities
149→        Vector2[] polyA;
150→        Vector2[] polyB;
151→
152→        if (hasBoxA)
153→        {
154→            SATCollision.BoxToPolygon(entity.Get<BoxCollider>(), entity.Get<Transform>(), _boxPolyBufA);
155→            polyA = _boxPolyBufA;
156→        }
157→        else
158→        {
159→            polyA = entity.Get<ConvexCollider>().WorldVertices;
160→        }
161→
162→        if (hasBoxB)
163→        {
164→            SATCollision.BoxToPolygon(target.Get<BoxCollider>(), target.Get<Transform>(), _boxPolyBufB);
165→            polyB = _boxPolyBufB;
166→        }
167→        else
168→        {
169→            polyB = target.Get<ConvexCollider>().WorldVertices;
170→        }
171→
172→        if (!SATCollision.PolygonVsPolygon(polyA, polyB, out var contactNormal, out var penetrationDepth)) return;
173→
174→        // Contact point: midpoint of centroids
175→        var contactPoint = (SATCollision.PolygonCenter(polyA) + SATCollision.PolygonCenter(polyB)) / 2f;
176→
177→        foreach (var layer in colliderB.SharedLayers(colliderA))
178→        {
179→            _world.Publish(_createCollisionMessage(entity, target, contactPoint, contactNormal, 0f, penetrationDepth, layer));
180→        }
181→    }
182→
183→    private static bool RayVsRect(
184→        Vector2 rayOrigin, Vector2 rayDirection, CollisionRect target, out Vector2 contactPoint,
185→        out Vector2 contactNormal, out float closestHit)
186→    {
187→        closestHit = float.NaN;
188→        contactNormal = Vector2.Zero;
189→        contactPoint = Vector2.Zero;
190→
191→        var inverseDirection = Vector2.One / rayDirection;
192→        var closestDistance = (target.Position - rayOrigin) * inverseDirection;
193→        var furthestDistance = (target.Position + target.Size - rayOrigin) * inverseDirection;
194→
195→        if (float.IsNaN(furthestDistance.Y) || float.IsNaN(furthestDistance.X)) return false;
196→        if (float.IsNaN(closestDistance.Y) || float.IsNaN(closestDistance.X)) return false;
197→
198→        if (closestDistance.X > furthestDistance.X) (closestDistance.X, furthestDistance.X) = (furthestDistance.X, closestDistance.X);
199→        if (closestDistance.Y > furthestDistance.Y) (closestDistance.Y, furthestDistance.Y) = (furthestDistance.Y, closestDistance.Y);
200→
201→        if (closestDistance.X > furthestDistance.Y || closestDistance.Y > furthestDistance.X) return false;
202→
203→        closestHit = Math.Max(closestDistance.X, closestDistance.Y);
204→        var furthestHit = Math.Min(furthestDistance.X, furthestDistance.Y);
205→
206→        if (furthestHit < 0) return false;
207→
208→        contactPoint = rayOrigin + closestHit * rayDirection;
209→
210→        if (closestDistance.X > closestDistance.Y)
211→            contactNormal = inverseDirection.X < 0 ? new Vector2(1, 0) : new Vector2(-1, 0);
212→        else if (closestDistance.X < closestDistance.Y)
213→            contactNormal = inverseDirection.Y < 0 ? new Vector2(0, 1) : new Vector2(0, -1);
214→
215→        return true;
216→    }
217→
218→    public static bool DynamicRectVsRect(
219→        in CollisionRect dynamicRect, in Vector2 displacement, in CollisionRect staticRect,
220→        out Vector2 contactPoint, out Vector2 contactNormal, out float contactTime)
221→    {
222→        if (displacement is { X: 0, Y: 0 })
223→        {
224→            contactPoint = Vector2.Zero;
225→            contactNormal = Vector2.Zero;
226→            contactTime = 0;
227→            return dynamicRect.Intersects(staticRect);
228→        }
229→
230→        var expandedTarget = new CollisionRect(
231→            staticRect.Position - dynamicRect.Size / 2,
232→            staticRect.Size + dynamicRect.Size);
233→
234→        var potentialCollision = RayVsRect(
235→            dynamicRect.Center, displacement, expandedTarget, out contactPoint,
236→            out contactNormal, out contactTime);
237→
238→        return potentialCollision && contactTime < 1.0f;
239→    }
240→
241→    private static ICollider GetCollider(Entity entity)
242→    {
243→        if (entity.Has<BoxCollider>()) return entity.Get<BoxCollider>();
244→        if (entity.Has<ConvexCollider>()) return entity.Get<ConvexCollider>();
245→        return null;
246→    }
247→
248→    public void Dispose()
249→    {
250→        _activeSet?.Dispose();
251→    }
252→}
